function selection(name,value,label){const box=node('input');box.type='checkbox';box.name=name;box.value=value;box.setAttribute('aria-label',label);return box}
const selected=(root,name)=>Array.from(root.querySelectorAll(`input[name="${name}"]:checked`),x=>x.value);
async function moderationBoards(writable=true){const d=await f('');return d.boards.filter(b=>b.permissions?.['thread:moderate']&&b.node_type==='forum'&&(!writable||b.effective_state==='open')).map(b=>[b.id,(d.categories.find(c=>c.id===b.category_id)?.name||'')+' / '+b.name]);}
function requireSelection(ids){if(!ids.length)throw Error('Выберите хотя бы один элемент.');return ids}
function bulkControls(topics,id){const box=panel();add(box,node('h3','Массовые действия'),button('Выбрать все темы',()=>{for(const el of topics.querySelectorAll('input[name="thread-selection"]'))el.checked=true}));for(const [action,label] of [['lock','Закрыть выбранные'],['unlock','Открыть выбранные'],['pin','Закрепить выбранные'],['unpin','Открепить выбранные']])add(box,button(label,async()=>{await f('/thread-actions/bulk','POST',{action,thread_ids:requireSelection(selected(topics,'thread-selection'))});await board(id)}));add(box,button('Перенести выбранные',async()=>{const ids=requireSelection(selected(topics,'thread-selection')),choices=await moderationBoards();if(!choices.length)throw Error('Нет доступных разделов.');const move=nodeForm([], [selectField('board_id','Целевой раздел',choices,choices.some(x=>x[0]===id)?id:choices[0]?.[0])],'Подтвердить перенос',async data=>{if(!confirm('Перенести выбранные темы? К содержимому будут применены права целевого раздела.'))return;await f('/thread-actions/bulk','POST',{action:'move',thread_ids:ids,board_id:data.board_id});await board(id)});box.querySelector('form')?.remove();add(box,move)}));return box}
// Selection is by UUID but the user can browse real topics with pagination.
async function topicPicker(exclude,multiple=false){const wrap=node('div'),choices=await moderationBoards(!multiple);if(!choices.length)throw Error('Нет доступных разделов.');const field=selectField('picker_board','Раздел с темами',choices,choices[0][0]),sel=field.querySelector('select'),results=node('div'),keep=new Map();let current=1,serial=0;
 async function load(){const n=++serial;results.replaceChildren(node('p','Загрузка…'));const d=await f('/boards/'+sel.value+'?page='+current);if(n!==serial)return;results.replaceChildren();for(const t of d.threads.filter(t=>t.id!==exclude)){const b=selection('picked_topic',t.id,t.title);b.checked=keep.has(t.id);b.addEventListener('change',()=>{if(b.checked){if(!multiple){keep.clear();for(const x of results.querySelectorAll('input'))if(x!==b)x.checked=false}keep.set(t.id,t.title)}else keep.delete(t.id);summary.textContent='Выбрано: '+Array.from(keep.values()).join(', ')});add(results,add(node('label'),b,node('span',t.title)))}if(current>1)add(results,button('Предыдущие темы',async()=>{current--;await load()}));if(d.threads.length===25)add(results,button('Следующие темы',async()=>{current++;await load()}));}
 const summary=node('p','Выбрано: 0','meta');sel.addEventListener('change',()=>run(async()=>{current=1;await load()}));add(wrap,field,results,summary,button('Сбросить выбор',async()=>{keep.clear();summary.textContent='Выбрано: 0';await load()}));await load();return {element:wrap,ids:()=>Array.from(keep.keys())};}
function discussionControls(d,id){const t=d.thread,box=panel(),body=node('div');add(box,node('h3','Управление обсуждением'),body);const show=el=>body.replaceChildren(el);
 add(box,button('Префикс и теги',()=>{const editor=form([['prefix','Префикс','text',t.prefix||''],['tags','Теги через запятую','text',(t.tags||[]).join(', ')]],'Сохранить метаданные',async data=>{await f('/threads/'+id+'/metadata','PUT',{prefix:data.prefix,tags:data.tags.split(',').map(x=>x.trim()).filter(Boolean)});await thread(id)});for(const el of editor.querySelectorAll('input'))el.required=false;show(editor)}),button('Перенести тему',async()=>{const choices=await moderationBoards();show(nodeForm([], [selectField('board_id','Целевой раздел',choices,choices.some(x=>x[0]===t.board_id)?t.board_id:choices[0]?.[0])],'Перенести',async data=>{if(!confirm('Применить к теме права целевого раздела?'))return;await f('/thread-actions/bulk','POST',{action:'move',thread_ids:[id],board_id:data.board_id});await thread(id)}))}),button('Объединить темы',async()=>{const picker=await topicPicker(id,true);show(add(node('div'),node('p','Выберите исходные темы, которые будут добавлены к текущей.'),picker.element,button('Подтвердить объединение',async()=>{const ids=requireSelection(picker.ids());if(!confirm('Объединить темы в текущую? Исходные ссылки будут вести сюда, права станут правами текущего раздела.'))return;await f('/threads/'+id+'/merge','POST',{source_ids:ids});await thread(id)})))}),button('Разделить тему',async()=>{const ids=requireSelection(selected(app,'post-selection')),choices=await moderationBoards();show(nodeForm([['title','Название новой темы']], [selectField('board_id','Целевой раздел',choices,choices.some(x=>x[0]===t.board_id)?t.board_id:choices[0]?.[0])],'Создать отдельную тему',async data=>{if(!confirm('Перенести выбранные ответы в новую тему?'))return;const result=await f('/threads/'+id+'/transfer','POST',{post_ids:ids,board_id:data.board_id,title:data.title});go(threadUrl(result))}))}),button('Перенести ответы',async()=>{const ids=requireSelection(selected(app,'post-selection')),picker=await topicPicker(id);show(add(node('div'),picker.element,button('Подтвердить перенос ответов',async()=>{const target=requireSelection(picker.ids())[0];if(!confirm('Перенести выбранные ответы? Применятся права целевой темы.'))return;const result=await f('/threads/'+id+'/transfer','POST',{post_ids:ids,target_id:target});go(threadUrl(result))})))}));add(box,node('p','Для разделения или переноса отметьте ответы ниже. Первое сообщение остаётся в исходной теме.','meta'));return box;}

async function unread(){heading('Непрочитанные темы');if(!me){add(app,link('Войти','/forum/login'));return}const d=await f('/unread?page='+page);add(app,markScope('all'),list(d,threadUrl),paging(d.length))}
async function latest(){heading('Последние обсуждения');const d=await f('/latest?page='+page);add(app,list(d,threadUrl),paging(d.length))}
const visibilityChoices=[['public','Все'],['members','Участники'],['private','Только я']];
let profileSettings=null;
function applyPreferences(p){if(!p)return;document.documentElement.dataset.theme=p.theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):p.theme;profileSettings=p}
function dateLabel(value){if(!value)return '';const raw=String(value);const stamp=/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d+)?$/.test(raw)?raw.replace(' ','T')+'Z':raw;const date=new Date(stamp);if(Number.isNaN(date.valueOf()))return raw;try{return new Intl.DateTimeFormat(profileSettings?.locale||'ru-RU',{dateStyle:'medium',timeStyle:'short',timeZone:profileSettings?.timezone||'UTC'}).format(date)}catch{return raw}}
function profilePicture(url,cls){const image=node('img',undefined,cls);image.src=url;image.alt=cls==='profile-cover'?'Обложка профиля':'Аватар';image.loading='lazy';return image}
async function profile(id){const d=await f('/members/'+id+'?page='+page),m=d.member;heading(m.name);const p=panel();if(m.cover_url)add(p,profilePicture(m.cover_url,'profile-cover'));const top=node('div',undefined,'profile-heading');if(m.avatar_url)add(top,profilePicture(m.avatar_url,'profile-avatar'));add(top,node('h2',m.name));add(p,top,node('p','Участник с '+dateLabel(m.created_at)));if(m.bio)add(p,node('div',m.bio,'profile-text'));if(m.location)add(p,node('p','Местоположение: '+m.location));if(m.website){const a=link(m.website,m.website);a.rel='nofollow noopener noreferrer';add(p,a)}if(m.groups?.length)add(p,node('p',m.groups.map(g=>g.name+(Number(g.is_primary)?' (основная)':'')).join(' · ')));for(const field of m.fields||[])add(p,node('p',field.label+': '+field.field_value));if(m.signature)add(p,node('div',m.signature,'profile-signature'));if(me?.user_id===id)add(p,link('Редактировать профиль','/forum/account/profile','button secondary'));if(isAdmin()){const controls=node('div',undefined,'actions');for(const [field,label] of [['bio','описание'],['signature','подпись'],['avatar','аватар'],['cover','обложку']])add(controls,button('Очистить '+label,async()=>{if(!confirm('Очистить '+label+'?'))return;await f('/members/'+id+'/moderate-profile','POST',{field});await profile(id)}));add(p,controls)}add(app,p);if(m.activity_visible)add(app,node('h3','Темы пользователя'),list(d.threads,threadUrl),paging(d.threads.length));else add(app,node('p','Активность скрыта.'))}
