async function profileFieldAdmin(){const p=panel();add(p,node('h3','Пользовательские поля профиля'));const fields=await f('/profile-fields');const draw=(field)=>{const [el,save]=settingsForm(field?'Сохранить поле':'Добавить поле',async form=>{const data=Object.fromEntries(new FormData(form));data.position=Number(data.position);await f('/profile-fields'+(field?'/'+field.id:''),field?'PUT':'POST',data);await manage()});const position=optionalField('position','Порядок',String(field?.position??0),5);position.querySelector('input').type='number';position.querySelector('input').min=0;add(el,optionalField('label','Название поля',field?.label,80),selectField('visibility','Видимость',visibilityChoices,field?.visibility||'public'),position,save);if(field)add(el,button('Удалить поле',async()=>{if(!confirm('Удалить поле и все его значения?'))return;await f('/profile-fields/'+field.id,'DELETE');await manage()},'danger'));return el};for(const field of fields)add(p,draw(field));add(p,draw(null));const [moderation,save]=settingsForm('Очистить содержимое профиля',async el=>{const data=Object.fromEntries(new FormData(el));if(!confirm('Очистить выбранное поле пользователя?'))return;await f('/members/'+data.user_id+'/moderate-profile','POST',{field:data.field});say('Содержимое профиля очищено.');await manage()});const users=await api('/users');add(moderation,selectField('user_id','Пользователь',users.map(u=>[u.id,u.name]),users[0]?.id||''),selectField('field','Очистить',[['bio','Описание'],['signature','Подпись'],['avatar','Аватар'],['cover','Обложку']],'bio'),save);add(p,node('h3','Модерация профилей'),moderation);return p}
