function nodeForm(fields,extras,submit,fn){const el=form(fields,submit,fn),button=el.querySelector('button');for(const extra of extras)el.insertBefore(extra,button);return el}
const typeChoices=[['forum','Форум'],['container','Контейнер']];
const stateChoices=[['open','Открыт'],['readonly','Только чтение'],['archived','Архив']];
function destinations(d,excluded=null){const result=[];const descend=(category,parent,prefix)=>{for(const b of d.boards.filter(x=>x.category_id===category&&(x.parent_id??null)===parent)){if(b.id===excluded)continue;result.push([`${category}:${b.id}`,prefix+' / '+b.name]);descend(category,b.id,prefix+' / '+b.name)}};for(const c of d.categories){result.push([`${c.id}:`,c.name]);descend(c.id,null,c.name)}return result}
const aclPermissions=['node:view','thread:read','thread:create','post:reply','post:edit_own','post:edit_any','reaction:use','watch:use','report:create','thread:moderate'];
const permissionTitles={'node:view':'Просмотр раздела','thread:read':'Чтение тем','thread:create':'Создание тем','post:reply':'Ответы','post:edit_own':'Свои сообщения','post:edit_any':'Чужие сообщения','reaction:use':'Реакции','watch:use':'Подписки','report:create':'Жалобы','thread:moderate':'Модерация'};
const effectChoices=[['inherit','Наследовать'],['allow','Разрешить'],['deny','Запретить'],['never','Никогда']];
function aclEditor(kind,id){const panelEl=panel(),path=`/${kind}/${id}/permissions`;add(panelEl,button('Разрешения',async()=>{
 const [data,roles,users]=await Promise.all([f(path),api('/roles'),api('/users')]);const rules=data.rules.map(({subject_type,subject_id,permission,effect})=>({subject_type,subject_id,permission,effect}));
 const visibility=selectField('visibility','Доступ',[['public','Открытый'],['private','Закрытый'],['hidden','Скрытый']],data.visibility);
 const subjects=[['everyone','Все'],['guest','Гости'],['authenticated','Авторизованные'],...roles.map(r=>['role:'+r.id,'Роль: '+r.name]),...users.map(u=>['user:'+u.id,'Пользователь: '+u.name+' ('+u.email+')'])];
 for(const r of rules){const key=r.subject_type+(r.subject_id?':'+r.subject_id:'');if(!subjects.some(x=>x[0]===key))subjects.push([key,key]);}
 const picker=selectField('subject','Субъект матрицы',subjects,'everyone'),subject=picker.querySelector('select'),matrix=node('div',undefined,'acl-scroll'),summary=node('p',undefined,'meta');
 const table=node('table',undefined,'acl-matrix');const head=node('tr');add(head,node('th','Разрешение'),node('th','Локальное правило'));add(table,add(node('thead'),head));const tbody=node('tbody');add(table,tbody);add(matrix,table);
 const draw=()=>{tbody.replaceChildren();const [subject_type,subject_id='']=subject.value.split(':');for(const permission of aclPermissions){const effect=rules.find(r=>r.subject_type===subject_type&&r.subject_id===subject_id&&r.permission===permission)?.effect||'inherit';const label=selectField('effect','',effectChoices,effect),sel=label.querySelector('select');sel.setAttribute('aria-label',permissionTitles[permission]);sel.dataset.permission=permission;sel.addEventListener('change',()=>{const index=rules.findIndex(r=>r.subject_type===subject_type&&r.subject_id===subject_id&&r.permission===permission);if(index>=0)rules.splice(index,1);if(sel.value!=='inherit')rules.push({subject_type,subject_id,permission,effect:sel.value});summary.textContent='Несохранённые изменения · правил: '+rules.length});const th=node('th',permissionTitles[permission]);th.scope='row';add(tbody,add(node('tr'),th,add(node('td'),sel)))}summary.textContent='Правил в текущем черновике: '+rules.length};subject.addEventListener('change',draw);draw();
 const save=button('Сохранить разрешения',async()=>{if(!confirm('Применить новые правила доступа?'))return;save.disabled=true;try{await f(path,'PUT',{visibility:visibility.querySelector('select').value,rules,revision:data.revision});await manage();say('Разрешения сохранены.')}finally{save.disabled=false}});
 panelEl.replaceChildren(node('h4','Матрица прав'),node('p','Выберите группу или пользователя. Изменения всех субъектов сохраняются вместе. Наследовать удаляет локальное правило; Never действует на потомков. Закрытый родитель недоступен целиком.'),visibility,picker,matrix,summary,save,permissionInspector(kind,id,users));
}));return panelEl}
function permissionInspector(kind,id,users){const box=node('section',undefined,'permission-inspector'),result=node('div');const choice=selectField('inspect_user','Проверить права',['guest'].map(x=>[x,'Гость']).concat(users.map(u=>[u.id,u.name+' ('+u.email+')'])),'guest');let serial=0;
 add(box,node('h4','Эффективные разрешения'),node('p','Проверяются сохранённые правила для нового входа пользователя. Ограничения отдельного API-токена не учитываются.'),choice,button('Проверить',async()=>{const n=++serial;const q=new URLSearchParams({kind:kind==='boards'?'board':'category',id});const user=choice.querySelector('select').value;if(user!=='guest')q.set('user_id',user);result.replaceChildren(node('p','Проверка…'));try{const d=await f('/permission-inspector?'+q);if(n!==serial)return;result.replaceChildren();const tr=d.trace;add(result,node('p',d.user?d.user.name+' · '+d.user.status:'Гость'));if(tr.inactive)add(result,node('p','Аккаунт неактивен: вход запрещён.'));if(tr.administrator)add(result,node('p','Системный администратор: обход ACL.'));if(d.publication_state)add(result,node('p','Состояние публикации: '+stateLabel(d.publication_state)+(d.node_type==='container'?' · контейнер не принимает темы':'')));const table=node('table',undefined,'acl-matrix'),header=add(node('tr'),node('th','Право'),node('th','Итог'));add(table,add(node('thead'),header));const rows=node('tbody');for(const perm of aclPermissions){const th=node('th',permissionTitles[perm]);th.scope='row';add(rows,add(node('tr'),th,node('td',d.effective[perm]?'Разрешено':'Запрещено',d.effective[perm]?'acl-allow':'acl-deny')))}add(table,rows);add(result,add(node('div',undefined,'acl-scroll'),table));if(tr.baseline){const details=node('details');add(details,node('summary','Глобальные ограничения и наследование'),node('p',tr.delegated_moderation?'Делегированная модерация требует явного ACL.':'Базовые права из ролей.'));for(const step of tr.steps){add(details,node('h5',step.name+' · '+step.visibility+(step.blocked?' · доступ прерван':'')));if(step.matched_rules.length)for(const r of step.matched_rules)add(details,node('p',`${r.permission} — ${r.effect} (${r.subject_type}${r.subject_id?' '+r.subject_id:''})`,'meta'));else add(details,node('p','Нет совпадающих локальных правил.','meta'));if(step.never.length)add(details,node('p','Never: '+step.never.join(', ')));add(details,node('p','Разрешено после шага: '+Object.keys(step.effective).filter(k=>step.effective[k]).join(', '),'meta'))}add(result,details)}}catch(e){if(n===serial){result.replaceChildren(node('p',e.message,'error'));throw e}}}),result);choice.querySelector('select').addEventListener('change',()=>{serial++;result.replaceChildren()});return box;
}
// Relative targets are resolved by the server under the tree lock, never by stale DOM positions.
function reorderTree(d){const box=panel(),status=node('p','Выберите узел кнопкой или перетащите его на подходящую цель.','meta');status.setAttribute('role','status');const entries=[],byId=new Map(d.boards.map(b=>[b.id,b]));let source=null,busy=false;
 const valid=(target,placement)=>{if(!source||source.id===target.id||busy)return false;if(source.kind==='category')return target.kind==='category'&&placement!=='inside';if(target.kind==='category')return placement==='inside';let cursor=target.id,seen=new Set();while(cursor&&!seen.has(cursor)){if(cursor===source.id)return false;seen.add(cursor);cursor=byId.get(cursor)?.parent_id}return true};
 const refresh=()=>{for(const e of entries){e.handle.setAttribute('aria-pressed',String(source?.id===e.item.id));for(const [placement,b] of e.targets){b.setAttribute('aria-disabled',String(!valid(e.item,placement)));b.classList.toggle('drop-ready',valid(e.item,placement))}}status.textContent=source?'Выбран: '+source.name+'. Укажите цель и положение.':'Выберите узел кнопкой или перетащите его на подходящую цель.'};
 const apply=async(target,placement)=>{if(!valid(target,placement))return;const moving=source;busy=true;refresh();try{if(moving.kind==='board'&&!confirm('Переместить «'+moving.name+'»? Наследуемые права могут измениться.'))return;await f('/nodes/reorder','POST',{kind:moving.kind,id:moving.id,target_kind:target.kind,target_id:target.id,placement});await manage();document.getElementById('reorder-'+moving.id)?.focus();say('Порядок разделов сохранён.')}finally{busy=false;source=null;refresh()}};
 const make=(item)=>{const row=node('li',undefined,'reorder-item'),line=node('div',undefined,'reorder-line');const handle=button('Переместить '+item.name,()=>{source=source?.id===item.id?null:item;refresh()});handle.id='reorder-'+item.id;handle.draggable=true;handle.setAttribute('aria-pressed','false');handle.addEventListener('dragstart',e=>{if(busy){e.preventDefault();return}source=item;e.dataTransfer.setData('text/plain',item.id);e.dataTransfer.effectAllowed='move';refresh()});handle.addEventListener('dragend',()=>{if(!busy){source=null;refresh()}});add(line,handle,node('span',item.kind==='category'?'Категория':item.node_type==='container'?'Контейнер':'Форум','meta'));const targets=[];
 for(const [placement,label] of [['before','До'],['inside','Внутрь'],['after','После']]){const b=button(label,()=>apply(item,placement),'secondary drop-target');b.setAttribute('aria-label',label+' '+item.name);b.dataset.placement=placement;b.addEventListener('dragover',e=>{if(valid(item,placement)){e.preventDefault();e.dataTransfer.dropEffect='move';b.classList.add('drop-over')}});b.addEventListener('dragleave',()=>b.classList.remove('drop-over'));b.addEventListener('drop',e=>{e.preventDefault();b.classList.remove('drop-over');if(valid(item,placement))run(()=>apply(item,placement))});targets.push([placement,b]);add(line,b)}entries.push({item,handle,targets});add(row,line);return row};
 const seen=new Set();const branch=(category,parent)=>{const ul=node('ul',undefined,'reorder-list');for(const b of d.boards.filter(x=>x.category_id===category&&(x.parent_id??null)===parent)){if(seen.has(b.id))continue;seen.add(b.id);const row=make({...b,kind:'board'});add(row,branch(category,b.id));add(ul,row)}return ul};const tree=node('ul',undefined,'reorder-list');for(const c of d.categories){const row=make({...c,kind:'category'});add(row,branch(c.id,null));add(tree,row)}add(box,node('h3','Порядок и перемещение разделов'),status,button('Отменить выбор',()=>{source=null;refresh()}),tree);box.addEventListener('keydown',e=>{if(e.key==='Escape'&&!busy){source=null;refresh()}});refresh();return box;
}
