async function groupAdmin(){
 const groups=await f('/groups'), users=await api('/users'), box=panel();
 add(box,node('h3','Группы пользователей'),node('p','Основная группа определяет основное членство, дополнительные группы добавляют права. Для делегированной модерации настройте разрешения раздела. Системные роли ядра не изменяются.'));
 const editFields=(g=null)=>{const el=node('form');const field=(key,label,value)=>{const input=node('input');input.name=key;input.value=value;input.required=true;add(el,add(node('label',label),input))};if(!g)field('handle','Handle новой группы','');field('name','Название группы',g?.name||'');const desc=node('textarea');desc.name='description';desc.value=g?.description||'';add(el,add(node('label','Описание группы'),desc));const checks=[];for(const [scope,label] of [['forum:write','Публикация сообщений'],['forum:moderate','Делегированная модерация']]){const input=node('input');input.type='checkbox';input.value=scope;input.checked=g?g.permissions.includes(scope):scope==='forum:write';checks.push(input);add(el,add(node('label',label),input))}const submit=node('button',g?'Сохранить группу':'Создать группу');submit.type='submit';add(el,submit);el.addEventListener('submit',e=>{e.preventDefault();run(async()=>{submit.disabled=true;try{const data=Object.fromEntries(new FormData(el));data.permissions=checks.filter(x=>x.checked).map(x=>x.value);await f(g?'/groups/'+g.id:'/groups',g?'PATCH':'POST',data);await manage();say('Группа сохранена.')}finally{submit.disabled=false}})});return el};
 add(box,editFields());for(const g of groups){const card=panel();add(card,node('h4',g.name),node('p',g.handle+' · '+(g.permissions.join(', ')||'Только чтение'),'meta'));if(g.system)add(card,node('p','Системная группа'));else add(card,editFields(g),button('Удалить группу',async()=>{if(confirm('Удалить пустую группу?')){await f('/groups/'+g.id,'DELETE');await manage()}},'danger'));add(box,card)}
 const membership=panel();add(membership,node('h3','Назначения групп'));const choices=users.map(u=>[u.id,u.name+' ('+u.email+')']);const picker=selectField('member','Пользователь',choices,choices[0]?.[0]||'');const target=node('div');let serial=0;const load=async()=>{const id=picker.querySelector('select').value,n=++serial;target.replaceChildren();if(!id)return;const data=await f('/members/'+id+'/groups');if(n!==serial)return;const formEl=node('form'),primary=selectField('primary_group_id','Основная группа',groups.map(g=>[g.id,g.name]),data.primary_group_id||groups[0]?.id||'');add(formEl,primary);const extra=[];for(const g of groups){const input=node('input');input.type='checkbox';input.value=g.id;input.checked=data.secondary_group_ids.includes(g.id);extra.push(input);add(formEl,add(node('label','Дополнительная: '+g.name),input))}const synchronize=()=>{for(const input of extra){input.disabled=input.value===primary.querySelector('select').value;if(input.disabled)input.checked=false}};primary.querySelector('select').addEventListener('change',synchronize);synchronize();const submit=node('button','Сохранить назначения');submit.type='submit';add(formEl,submit);formEl.addEventListener('submit',e=>{e.preventDefault();run(async()=>{submit.disabled=true;try{await f('/members/'+id+'/groups','PUT',{primary_group_id:primary.querySelector('select').value,secondary_group_ids:extra.filter(x=>x.checked&&!x.disabled).map(x=>x.value)});await load();say('Назначения сохранены.')}finally{submit.disabled=false}})});add(target,formEl)};picker.querySelector('select').addEventListener('change',()=>run(load));add(membership,picker,target);await load();add(box,membership);return box;
}
async function manage(){heading('Управление форумом');if(!canModerate()){add(app,node('p','Требуются права модератора.'));return}const d=await f('');if(isAdmin())add(app,reorderTree(d),await groupAdmin(),await profileFieldAdmin(),nodeAdmin(d));add(app,node('h2','Открытые жалобы'));const reports=await f('/reports?page='+page);for(const r of reports){const b=panel();add(b,node('p',r.reason),node('div',r.body,'body'),link('Открыть тему',`/forum/threads/${r.thread_id}`),button('Закрыть жалобу',async()=>{await f(`/reports/${r.id}/resolve`,'POST');await manage()}));add(app,b)}if(!reports.length)add(app,node('p','Нет открытых жалоб.'));add(app,paging(reports.length))}
function mailPage(reset){heading(reset?'Восстановление пароля':'Повторное подтверждение email');add(app,form([['email','Email','email']],'Отправить письмо',async data=>{await api(reset?'/auth/password/forgot':'/auth/email/resend','POST',data);say('Если аккаунт подходит для операции, письмо будет отправлено. Повторная отправка доступна через минуту.')}),link('Войти','/forum/login'))}
function tokenPage(reset){heading(reset?'Новый пароль':'Подтверждение email');const token=new URLSearchParams(location.hash.slice(1)).get('token')||'';if(token)history.replaceState(null,'',location.pathname);if(!/^[a-f0-9]{64}$/.test(token)){add(app,node('p','Недействительная ссылка. Запросите новое письмо.'),link('Запросить письмо',reset?'/forum/forgot-password':'/forum/resend-email'));return}add(app,form([['password',reset?'Новый пароль':'Пароль, указанный при регистрации','password']],reset?'Сохранить пароль':'Подтвердить',async data=>{await api(reset?'/auth/password/reset':'/auth/email/verify','POST',{token,password:data.password});app.replaceChildren();heading(reset?'Пароль изменён':'Email подтверждён');add(app,link('Войти','/forum/login'))}))}
async function account(){heading('Настройки аккаунта');if(!me?.session){add(app,link('Войти','/forum/login'));return}add(app,link('Профиль и персональные настройки','/forum/account/profile','button secondary'));const p=panel();add(p,node('h2','Безопасность'),node('p','Email: '+me.user.email),node('p',me.user.two_factor_enabled?'2FA включена':'2FA выключена'));if(me.user.two_factor_enabled){add(p,form([['password','Текущий пароль','password'],['two_factor_code','Новый 2FA-код или код восстановления']],'Отключить 2FA',async data=>{await api('/auth/2fa/disable','POST',data);go('/forum/login')}))}else{add(p,form([['password','Текущий пароль','password']],'Настроить 2FA',async data=>{const setup=await api('/auth/2fa/enable','POST',data);p.replaceChildren(node('h2','Подключите приложение-аутентификатор'),node('p','Введите секрет вручную в приложении TOTP. SHA1, 6 цифр, 30 секунд.'),node('pre',setup.secret),node('p','Подтвердите код в течение 10 минут.'),form([['password','Текущий пароль','password'],['two_factor_code','6-значный код приложения']],'Подтвердить 2FA',async input=>{const result=await api('/auth/2fa/confirm','POST',{...input,setup_token:setup.setup_token});app.replaceChildren();heading('2FA включена');add(app,node('p','Сохраните коды восстановления в безопасном месте. Каждый код используется один раз. Повторный показ невозможен.'),node('pre',result.recovery_codes.join('\n')),link('Войти заново','/forum/login'));me=null}))}))}add(app,p);const q=panel();add(q,node('h2','Активные сессии'));const sessions=await api('/auth/sessions');for(const session of sessions){add(q,add(node('div',undefined,'entry'),node('p',(session.current?'Текущая сессия · ':'')+'Создана: '+session.created_at+' · Последняя активность: '+(session.last_used_at||'—')+' · Истекает: '+session.expires_at),button('Завершить',async()=>{await api('/auth/sessions/'+session.id,'DELETE');if(session.current)go('/forum/login');else{app.replaceChildren();await account()}})))}add(q,form([['password','Текущий пароль','password'],...(me.user.two_factor_enabled?[['two_factor_code','Новый 2FA-код или код восстановления']]:[])],'Завершить все сессии',async data=>{await api('/auth/sessions/revoke-all','POST',data);go('/forum/login')}));add(app,q)}
const notificationKinds={reply:'Новый ответ',mention:'Вас упомянули',quote:'Ваше сообщение процитировано',reaction:'Отметка «Нравится»',moderation:'Модерация обсуждения'};
let notificationRequest=0;
async function notificationBadge(){if(!me)return;const seq=++notificationRequest;try{const d=await f('/notifications?count_only=1');if(seq===notificationRequest)document.getElementById('notifications').textContent='Уведомления'+(d.unread?' ('+d.unread+')':'')}catch{/* Keep navigation usable while offline. */}}
async function notifications(){
 app.replaceChildren();heading('Уведомления');if(!me){add(app,link('Войти','/forum/login'));return}
 const d=await f('/notifications?page='+page),box=panel();
 add(box,node('h3',`Непрочитанных: ${d.unread}`),button('Отметить все прочитанными',async()=>{await f('/notifications/read','POST',{all:true});await notificationBadge();await notifications()}));
 if(!d.items.length)add(box,node('p','Нет уведомлений на этой странице.'));
 for(const item of d.items){const row=node('div',undefined,'entry notification-entry'+(item.is_read?'':' notification-unread'));const title=node('div');add(title,node('strong',item.kind==='moderation'?({lock:'Тема закрыта',unlock:'Тема открыта',pin:'Тема закреплена',unpin:'Тема откреплена'}[item.moderation_action]||notificationKinds.moderation):(notificationKinds[item.kind]||'Уведомление')),node('p',item.title),node('span',item.actor_name||'Участник','meta'),node('span',dateLabel(item.created_at),'meta'));const actions=node('div',undefined,'actions');add(actions,button('Перейти',async()=>{const current=await f('/notifications/'+item.id);await f('/notifications/read','POST',{id:item.id});go(`/forum/threads/${current.thread_id}?page=${current.page}#post-${current.post_id}`)}));if(!item.is_read)add(actions,button('Прочитано',async()=>{await f('/notifications/read','POST',{id:item.id});await notificationBadge();await notifications()}));add(row,title,actions);add(box,row)}
 add(app,box,paging(d.items.length));const prefs=panel();add(prefs,node('h3','Настройки уведомлений'),node('p','Настройки применяются к новым и ожидающим доставки событиям.'));const [el,save]=settingsForm('Сохранить уведомления',async form=>{const data={};for(const k of Object.keys(notificationKinds))data[k]=form.elements[k].checked;await f('/notification-preferences','PUT',data);say('Настройки уведомлений сохранены.');await notifications()});for(const [k,label] of Object.entries(notificationKinds))add(el,checkField(k,label,d.preferences[k]));add(el,save);add(prefs,el);add(app,prefs);
}
function referenceToReply(value){const field=document.getElementById('forum-reply-body');if(!field)return;field.value+=(field.value?'\n':'')+value+' ';field.focus();field.scrollIntoView({block:'center'});}
async function init(){applyPreferences({theme:'system',locale:'ru-RU',timezone:'UTC'});matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(profileSettings?.theme==='system')applyPreferences(profileSettings)});try{me=await api('/auth/me')}catch{}const s=document.getElementById('session');if(me){try{applyPreferences((await f('/account/profile')).preferences)}catch{}add(s,link(me.user?.name||'Участник','/forum/account'),button('Выйти',async()=>{await api('/auth/logout','POST');go('/forum')}));document.getElementById('unread').hidden=false;document.getElementById('notifications').hidden=false;void notificationBadge();setInterval(()=>{if(!document.hidden)void notificationBadge()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)void notificationBadge()});document.getElementById('watches').hidden=!canWrite();document.getElementById('manage').hidden=!canModerate()}else add(s,link('Вход','/forum/login'));const path=location.pathname.replace(/\/$/,'');let m;if(path===''||path==='/forum')await home();else if((m=path.match(/^\/forum\/boards\/([a-f0-9-]+)$/)))await board(m[1]);else if((m=path.match(/^\/forum\/threads\/([a-f0-9-]+)$/)))await thread(m[1]);else if(path==='/forum/members')await memberDirectory();else if(['/forum/account/profile','/forum/account/preferences','/forum/account/privacy'].includes(path))await profileAccount();else if(path==='/forum/search')await search();else if(path==='/forum/latest')await latest();else if(path==='/forum/unread')await unread();else if(path==='/forum/notifications')await notifications();else if((m=path.match(/^\/forum\/members\/([a-f0-9-]+)$/)))await profile(m[1]);else if(path==='/forum/login')auth();else if(path==='/forum/register')auth(true);else if(path==='/forum/resend-email')mailPage(false);else if(path==='/forum/forgot-password')mailPage(true);else if(path==='/forum/verify-email')tokenPage(false);else if(path==='/forum/reset-password')tokenPage(true);else if(path==='/forum/account'||path==='/forum/account/security'||path==='/forum/account/sessions')await account();else if(path==='/forum/watches')await watches();else if(path==='/forum/manage')await manage();else heading('Страница не найдена')}
run(init);
